head.script:
// 컴포넌트·전역 이름 조회(엔진 캐시 → 이름 그대로 실행 → mf_ 접두사 붙여 다시, 없으면 받은 id 문자열 반환). 2026-11
scwin.__getObj = function(id) {
	if (typeof id !== 'string') return id;
	var W = WebSquare, C = W.idCache, U = W.idToUUID, F = function(k) { return new Function('return ' + k)(); };
	if (!W.strictMode) id = id.replace(/mf_/g, '');
	if (C[U[id]]) return C[U[id]];
	var r; try { r = F(id); } catch (e) {}
	if (r == undefined && W.strictMode) {
		var P = W.strictModeFrame.id + '_';
		var s = id.slice(0, 2) === 'G_' ? 'G_' + P + id.slice(2) : (id.slice(0, P.length) !== P ? P + id : id);
		s = s.replace(new RegExp('(' + P + '){2,}', 'g'), P);
		if (C[U[s]]) r = C[U[s]]; else { try { r = F(s); } catch (e) { r = id; } }
	}
	return r == undefined ? id : r;
};
// jQuery 조회 순서(받은 선택자 → 없으면 mf_ 접두사). 2026-11
scwin.__getJq = function(q) {
	var j = $(q); if (j.length) return j;
	var P = 'mf_', t = q.trim(), r = t.slice(1);
	if (r.slice(0, 2) === 'G_') r = 'G_' + P + r.slice(2); else if (r.slice(0, P.length) !== P) r = P + r;
	return $(t.slice(0, 1) + r);
};
scwin.fn_expressionValue = function(rowIdx, col1Value, col2Value) {
	var returnValue = col2Value;
	if (col1Value == "sum") {
		gridView1.setCellColor(rowIdx, "col3", "red");
	} else {
		gridView1.setCellColor(rowIdx, "col3", "blue");
	}
	returnValue = WebSquare.util.setNumber(returnValue);
	return returnValue + "_test";
}
scwin.trigger1_onclick = function(e) {
	var jsonData = [
		{ "col1": "sum", "col2": "12345.00" },
		{ "col1": "avg", "col2": "123456.894" },
		{ "col1": "sum", "col2": "467890.00" },
		{ "col1": "avg", "col2": "123456.7" }
	];
	dataList1.setJSON(jsonData);
};
scwin.trigger3_onclick = function(e) {
	dataList1.removeAll();
};
scwin.trigger4_onclick = function(e) {
	dataList1.insertRow();
};
scwin.trigger7_onclick = function(e) {
	dataList1.removeRow(3);
};
scwin.trigger8_onclick = function(e) {
	dataList1.insertRow(2);
};
scwin.trigger9_onclick = function(e) {
	dataList1.removeRows([2, 3]);
};
scwin.isShowData = function() {
	var count = 0;
	((j) => j.length ? j : $('#mf_gridView1_body_tbody tr'))($('#gridView1_body_tbody tr')).not(".w2grid_hidedRow").each(function(i, el) {
		if (scwin.__getJq(this).text()) {
			count++;
		}
	});
	return count > 0;
}
scwin.setVal1 = function() {
	return beforeValue1 = scwin.__getObj('gridView1_cell_3_0').innerText;
}
scwin.setVal2 = function() {
	return beforeValue2 = scwin.__getObj('gridView1_cell_2_0').innerText;
}
scwin.checkVal1 = function() {
	return scwin.__getObj('gridView1_cell_3_0').innerText != beforeValue1;
}
scwin.checkVal2 = function() {
	return scwin.__getObj('gridView1_cell_2_0').innerText != beforeValue2;
}
scwin.onpageload = function() {
	window.beforeValue1 = undefined;
	window.beforeValue2 = undefined;
};
